/// TSX stores (`createStore<T>(initial)`): the framework's Zustand-style
/// store ([`crate::store`]), shared through an `Rc<RefCell<Store<T>>>`.
///
/// Zig's `tsx.Store(T)` rebuilt every window when it changed; generated Rust
/// calls `ui::request_rebuild()` (for the callback's window) and
/// `zant::desktop::invalidate_all()` (all windows) after a write.
pub use crate::store::{SharedStore, Store, create as create_store};

/// `Uint8Array` in TSX (`tsx.Bytes` in Zig): a cheap-to-clone byte buffer.
///
/// `Rc<[u8]>` keeps the "either `Copy` or cheaply `Clone`" rule of generated
/// values; bytes arriving from native code / the clipboard are converted once.
pub type Bytes = Rc<[u8]>;

/// A number accepted where JS reads a numeric index (`Array[i]`,
/// `sliceIndex`): floats are checked, integers are used as is.
pub trait JsNumber {
    fn to_f64(self) -> f64;
}

macro_rules! js_number_int {
    ($($ty:ty),* $(,)?) => {
        $(
            impl JsNumber for $ty {
                fn to_f64(self) -> f64 {
                    self as f64
                }
            }
        )*
    };
}

js_number_int!(i8, i16, i32, i64, isize, u8, u16, u32, u64, usize, f32);

impl JsNumber for f64 {
    fn to_f64(self) -> f64 {
        self
    }
}

/// A float value truncated / clamped into an integer type (`tsx.toInt`).
pub trait IntFromF64: Sized {
    const MIN: f64;
    const MAX: f64;
    fn from_truncated(value: f64) -> Self;
}

macro_rules! int_from_f64_signed {
    ($($ty:ty),* $(,)?) => {
        $(
            impl IntFromF64 for $ty {
                const MIN: f64 = <$ty>::MIN as f64;
                const MAX: f64 = <$ty>::MAX as f64;
                fn from_truncated(value: f64) -> Self {
                    value as $ty
                }
            }
        )*
    };
}

macro_rules! int_from_f64_unsigned {
    ($($ty:ty),* $(,)?) => {
        $(
            impl IntFromF64 for $ty {
                const MIN: f64 = 0.0;
                const MAX: f64 = <$ty>::MAX as f64;
                fn from_truncated(value: f64) -> Self {
                    value as $ty
                }
            }
        )*
    };
}

int_from_f64_signed!(i8, i16, i32, i64, isize);
int_from_f64_unsigned!(u8, u16, u32, u64, usize);

/// A TS `number` passed to an integer field (`size={n}`): truncated toward
/// zero and clamped to `T`'s range (NaN is 0), like the Zig `tsx.toInt`.
///
/// The Zig version let `@intFromFloat` panic when the clamped value rounded
/// out of range; the Rust version saturates (the codegen only uses this for
/// layout / list indexes where a clamp is what TSX wants).
pub fn to_int<T: IntFromF64>(value: f64) -> T {
    if value.is_nan() {
        return T::from_truncated(0.0);
    }
    T::from_truncated(value.trunc().clamp(T::MIN, T::MAX))
}

/// `<List scrollToIndex={i}>`: a negative / NaN index scrolls nowhere.
pub fn list_index(value: f64) -> Option<usize> {
    if value.is_nan() || value < 0.0 {
        return None;
    }
    Some(to_int(value))
}

/// `<List layoutKey={n}>`: any number, compared by value (its f64 bits).
pub fn list_key(value: f64) -> u64 {
    value.to_bits()
}

/// `str.length` with TypeScript's meaning: UTF-16 code units, not bytes
/// (`"周报".length` is 2, an emoji counts 2).
pub fn utf16_length(text: &str) -> usize {
    text.chars()
        .map(|character| if character as u32 > 0xffff { 2 } else { 1 })
        .sum()
}

/// A checked numeric index (`arr[value]`): neither negative, fractional nor
/// nonfinite (Zig `tsx.index` panicked on those instead of truncating).
pub trait IndexNumber {
    fn checked_index(self) -> usize;
}

macro_rules! index_int {
    ($($ty:ty),* $(,)?) => {
        $(
            impl IndexNumber for $ty {
                fn checked_index(self) -> usize {
                    self as usize
                }
            }
        )*
    };
}

macro_rules! index_signed {
    ($($ty:ty),* $(,)?) => {
        $(
            impl IndexNumber for $ty {
                fn checked_index(self) -> usize {
                    assert!(self >= 0, "invalid TSX index");
                    self as usize
                }
            }
        )*
    };
}

index_int!(u8, u16, u32, u64, usize);
index_signed!(i8, i16, i32, i64, isize);

impl IndexNumber for f64 {
    fn checked_index(self) -> usize {
        assert!(
            self.is_finite() && self >= 0.0 && self.trunc() == self,
            "invalid TSX index"
        );
        self as usize
    }
}

impl IndexNumber for f32 {
    fn checked_index(self) -> usize {
        f64::from(self).checked_index()
    }
}

/// A checked array index (`tsx.index`): panics on negative / fractional /
/// nonfinite values instead of silently truncating JavaScript numbers.
pub fn index<I: IndexNumber>(value: I) -> usize {
    value.checked_index()
}

/// Slice endpoints follow JS clamping and negative-offset rules.
pub fn slice_index<V: JsNumber>(value: V, length: usize) -> usize {
    let number = value.to_f64();
    if number.is_nan() {
        return 0;
    }
    let len = length as f64;
    let clamped = len.min(0.0f64.max(if number < 0.0 {
        len + number.trunc()
    } else {
        number.trunc()
    }));
    clamped as usize
}

/// An element of [`join`]: a generated string value (`Str` / `&str` /
/// `String`).
pub trait JoinItem {
    fn join_str(&self) -> &str;
}

impl JoinItem for crate::Str {
    fn join_str(&self) -> &str {
        self.as_str()
    }
}

impl JoinItem for &str {
    fn join_str(&self) -> &str {
        self
    }
}

impl JoinItem for String {
    fn join_str(&self) -> &str {
        self
    }
}

/// `array.join(separator)`.
pub fn join<S: JoinItem>(items: &[S], separator: &str) -> crate::Str {
    let mut out = String::new();
    for (index, item) in items.iter().enumerate() {
        if index > 0 {
            out.push_str(separator);
        }
        out.push_str(item.join_str());
    }
    crate::Str::from(out)
}

/// Children with conditional entries (`{cond && <X/>}`): drops the `None`s
/// (Zig `tsx.nodes`).
pub fn nodes(items: impl IntoIterator<Item = Option<crate::ui::Node>>) -> Vec<crate::ui::Node> {
    items.into_iter().flatten().collect()
}

/// A null-only TS value used where another optional type is expected: always
/// `None` (`tsx.nullAs` in Zig kept argument evaluation order).
pub fn null_as<T>(value: Option<u8>) -> Option<T> {
    let _ = value;
    None
}

/// `?T` of any type viewed as a nullable value (`tsx.nullEqual`).
pub trait NullValue {
    fn is_null(&self) -> bool;
}

impl<T> NullValue for Option<T> {
    fn is_null(&self) -> bool {
        self.is_none()
    }
}

/// Compare a null-only value while preserving argument evaluation order.
pub fn null_equal<A: NullValue, B: NullValue>(left_null: bool, a: A, b: B) -> bool {
    if left_null { b.is_null() } else { a.is_null() }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ui::builders::text;
    use crate::ui::options::TextOptions;

    #[test]
    fn nodes_drops_null_children() {
        let a = text("a", TextOptions::default());
        let b = text("b", TextOptions::default());
        let out = nodes([Some(a), None, Some(b.clone()), None]);
        assert_eq!(out.len(), 2);
        assert!(out[1].ptr_eq(&b));
        let formatted = format!("x={} {}", 3, "on");
        assert_eq!(formatted, "x=3 on");
    }

    #[test]
    fn to_int_truncates_and_clamps() {
        assert_eq!(to_int::<usize>(2.9), 2);
        assert_eq!(to_int::<usize>(-3.0), 0);
        assert_eq!(to_int::<i32>(-3.7), -3);
        assert_eq!(to_int::<u8>(1e9), 255);
        assert_eq!(to_int::<u8>(f64::NAN), 0);
        assert_eq!(to_int::<i64>(1e300), i64::MAX);
    }

    #[test]
    fn utf16_length_counts_code_units() {
        assert_eq!(utf16_length(""), 0);
        assert_eq!(utf16_length("hello"), 5);
        assert_eq!(utf16_length("周五前交周报"), 6);
        assert_eq!(utf16_length("📌 "), 3);
    }

    #[test]
    fn list_helpers_follow_the_zig_rules() {
        assert_eq!(list_index(3.0), Some(3));
        assert_eq!(list_index(-1.0), None);
        assert_eq!(list_index(f64::NAN), None);
        assert_eq!(list_index(2.9), Some(2));
        assert_eq!(list_key(1.5), 1.5f64.to_bits());
        assert_eq!(list_key(-0.0), (-0.0f64).to_bits());
    }

    #[test]
    fn indexes_are_checked_like_the_zig_panic() {
        assert_eq!(index(2.0), 2);
        assert_eq!(index(7u32), 7);
        for value in [-1.0, 1.5, f64::NAN, f64::INFINITY] {
            let result = std::panic::catch_unwind(|| index(value));
            assert!(result.is_err(), "{value} must be invalid");
        }
        let result = std::panic::catch_unwind(|| index(-1i32));
        assert!(result.is_err());
    }

    #[test]
    fn slice_index_clamps_and_counts_negatives_from_the_end() {
        assert_eq!(slice_index(2.0, 4), 2);
        assert_eq!(slice_index(-1.0, 4), 3);
        assert_eq!(slice_index(-100.0, 4), 0);
        assert_eq!(slice_index(100.0, 4), 4);
        assert_eq!(slice_index(f64::NAN, 4), 0);
        assert_eq!(slice_index(2i32, 4), 2);
    }

    #[test]
    fn join_and_null_helpers() {
        let parts = vec![crate::Str::from("a"), crate::Str::from("b")];
        assert_eq!(join(&parts, ", ").as_str(), "a, b");
        assert_eq!(join(&[] as &[&str], "-").as_str(), "");
        let nil: Option<u8> = None;
        assert!(null_as::<crate::ui::Node>(nil).is_none());
        assert!(!null_equal(true, nil, Some("text")));
        assert!(!null_equal(false, Some("text"), nil));
        assert!(null_equal(true, nil, None::<&str>));
    }
}
